import { dbEnvSchema, type Cleanup, type Logger, type ReadinessCheck } from '@app/server-kit';
import { createDb, type Knex } from '@app/server-kit/db';
import { z } from 'zod';

export const stack = {"service":"api","db":"own","uses":[],"calls":[]} as const;

/** Env vars wired in by stack.json (database, add-ons, called services). */
export const stackEnvSchema = z.object({
  ...dbEnvSchema.shape,
});

/** Connections to what stack.json gives this service. `undefined` = not declared there. */
export interface StackResources {
  db: Knex;
  redis: undefined;
  broker: undefined;
  /** Pass to createApp/buildApp: one /readyz check per connection. */
  readiness: Record<string, ReadinessCheck>;
  /** Pass to startServer({ onShutdown }): closes every connection. */
  cleanup: Cleanup[];
}

/** Connect to everything stack.json says this service uses (db, redis, rabbitmq). */
export async function connectStack(config: z.output<typeof stackEnvSchema>, logger: Logger): Promise<StackResources> {
  const readiness: Record<string, ReadinessCheck> = {};
  const cleanup: Cleanup[] = [];

  const db = createDb({ url: config.DATABASE_URL, schema: config.DB_SCHEMA, poolMax: config.DB_POOL_MAX, logger });
  readiness.db = () => db.raw('select 1');
  cleanup.push(() => db.destroy());

  return { db, redis: undefined, broker: undefined, readiness, cleanup };
}

